# Renommages probables connus (live herite -> depot) : a confirmer, jamais appliques auto.
ALIAS = {
  "immeubles": {"type_immeuble": "type", "description": "notes",
                "valeur_estimee": "valeur_bien", "valeur": "valeur_bien"},
}

def normaliser(brut):
    if isinstance(brut, dict) and all(isinstance(v, list) for v in brut.values()):
        out = {}
        for t, cols in brut.items():
            out[t] = [c["column_name"] if isinstance(c, dict) else str(c) for c in cols]
        return out
    if isinstance(brut, list):
        out = {}
        for row in brut:
            out.setdefault(row["table_name"], []).append(row["column_name"])
        return out
    raise ValueError("format de dump non reconnu")

def main(argv):
    if len(argv) != 2:
        print("usage: compare_schema_live.py <dump_live.json>"); return 2
    try:
        live = normaliser(json.loads(open(argv[1], encoding="utf-8").read()))
    except Exception as e:
        print(f"ERREUR d'entree : {e}"); return 2
    manquantes_total = 0
    for table in sorted(set(EXPECTED) | set(live)):
        if table not in live:
            print(f"\n### {table} : TABLE ABSENTE du dump live ({len(EXPECTED[table])} colonnes attendues)")
            manquantes_total += len(EXPECTED[table]); continue
        if table not in EXPECTED:
            print(f"\n### {table} : table live hors depot ({len(live[table])} colonnes) - a inventorier")
            continue
        exp, liv = EXPECTED[table], live[table]
        manquantes = [c for c in exp if c not in liv]
        en_trop = [c for c in liv if c not in exp]
        print(f"\n### {table} : attendues {len(exp)} / live {len(liv)} / manquantes {len(manquantes)} / en trop {len(en_trop)}")
        for c in manquantes:
            alias = [k for k, v in ALIAS.get(table, {}).items() if v == c and k in en_trop]
            proche = difflib.get_close_matches(c, en_trop, n=1, cutoff=0.6)
            hint = f"  <- renommage probable de '{alias[0]}'" if alias else (f"  <- proche de '{proche[0]}' ?" if proche else "")
            print(f"  MANQUANTE : {c} ({EXPECTED_DEFS[table][c]}){hint}")
        for c in en_trop:
            cible = ALIAS.get(table, {}).get(c)
            print(f"  EN TROP (heritage, ne pas supprimer) : {c}" + (f" -> correspond sans doute a '{cible}' du depot" if cible else ""))
        manquantes_total += len(manquantes)
    print(f"\n=== TOTAL colonnes manquantes : {manquantes_total} ===")
    return 1 if manquantes_total else 0

if __name__ == "__main__":
    sys.exit(main(sys.argv))
